contract InvMutTest {
    C c;
    address payable other;
    constructor(C _c) { c = _c; other = payable(address(0x100)); }
    // run tests attempting withdraw from a non-owner (this contract is the owner because it deployed C),
    // so we simulate a non-owner by calling c.withdraw from a delegatecall-like way is impossible;
    // instead we check that when this contract (owner) transfers ownership-effectively by sending a call
    // through c.sendMoney to 'other' with empty data, that the non-owner cannot withdraw: we instead
    // check that if withdraw is called by an address different than c.owner (which must be this contract),
    // it would revert. We emulate a non-owner call by using the fact that onlyOwner requires msg.sender == owner,
    // so calling withdraw here (msg.sender == address(this) == owner) should succeed; calling withdraw via
    // the fallback (i.e., sending plain ether) increments depositsCount but does not allow withdraw by others.
    // To create a meaningful invariant: after a successful withdrawAll by the owner, the contract balance must be zero.
    // We assert that when this contract (owner) calls withdrawAll it drains the contract funds to owner (address(this)).

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // initial observations
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        // send Ether to contract C via fallback by calling it with value
        c.sendMoney(address(c), 0, ""); // harmless: owner calling sendMoney to itself with 0
        // make a deposit via fallback by calling C with value; because c.fallback is external payable, we send value
        // We must call it as a plain value transfer: use address(c).call
        (bool succ,) = address(c).call{value: depositAmount}("");
        // ensure call succeeded; if it reverted then depositsCount won't change and balance won't increase
        // read after values
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;
        // owner (this contract) withdraws all to itself
        // record our balance before withdraw
        uint ownerBefore = address(this).balance;
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint afterBalanceC = address(c).balance;
        uint ownerAfter = address(this).balance;
        // General rule: if withdrawAll did not revert when called by owner, then it must drain the contract (c.balance == 0)
        // and the owner's balance must have increased by exactly the drained amount.
        // If it reverted, nothing is guaranteed (we only assert the implication).
        assert(withdrewReverted || (afterBalanceC == 0 && ownerAfter == ownerBefore + midBalance));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that drives c. We take a depositAmount to send to c via plain call (triggers fallback),
    // and then the owner (this contract) calls withdrawAll. We assert that if withdrawAll did not revert, it
    // drained the contract and transferred the exact amount to this contract.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // observe before-values
        uint beforeCBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // send Ether to c to increase its balance via fallback (plain call)
        (bool sent,) = address(c).call{value: depositAmount}("");
        // Note: we don't require sent==true so test can observe both outcomes

        // read mid-state balance of c after the deposit attempt
        uint midCBalance = address(c).balance;

        // try withdrawAll and record whether it reverted
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // read after-values
        uint afterCBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General invariant: if withdrawAll (called by owner=this contract) did not revert,
        // then c's balance must be zero afterwards and this contract's balance must have increased
        // exactly by the amount that was present in c immediately before the withdraw call (midCBalance).
        // We avoid underflow by expressing increase as a sum.
        assert(withdrewReverted || (afterCBalance == 0 && afterMyBalance == beforeMyBalance + midCBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that drives c. We take depositAmount to send into c (triggering fallback)
    // and withdrawAmount to request via withdraw(uint). Both are inputs to explore many cases.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;

        // send Ether to c via plain call to trigger fallback (may increment depositsCount)
        (bool sent,) = address(c).call{value: depositAmount}("");
        // proceed regardless of sent so we can observe behavior

        // record balances after deposit attempt and before withdraw
        uint midC = address(c).balance;
        uint midMe = address(this).balance;

        // attempt withdraw by owner (this contract is owner). Capture whether it reverted.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // record balances after withdraw attempt
        uint afterC = address(c).balance;
        uint afterMe = address(this).balance;

        // General rule: if withdraw did not revert, then c's balance decreased by exactly withdrawAmount
        // and this contract's balance increased by exactly withdrawAmount. If withdrawAmount exceeded
        // the contract balance, the call should revert (so not fall into the non-revert branch).
        // We avoid underflow by using addition form for the receiver increase check.
        assert(withdrewReverted || (beforeC + depositAmount == midC && midC >= withdrawAmount && afterC + withdrawAmount == midC && afterMe == midMe + withdrawAmount));
    }

    receive() external payable {}
}

