contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry that drives c. We take an amount and a dummy payload for sendMoney.
    function run(uint depositAmount, uint withdrawAmount, address attacker, bytes memory data) public payable {
        // Ensure this test contract has Ether available to deposit into c
        require(address(this).balance >= depositAmount);
        // Ensure attacker is not the owner (owner is the deployer of c, which is this contract), so attacker != address(this)
        require(attacker != address(this));

        // Record observed public state before interactions
        uint beforeDepositsCount = c.depositsCount();
        uint beforeCBalance = address(c).balance;

        // Deposit Ether into c by sending plain value to trigger fallback (top-level call via address call)
        (bool sent, ) = address(c).call{value: depositAmount}("\x00");
        // sent may be true or false; fallback increments depositsCount only on successful payable fallback execution

        // Record observed public state after deposit attempt
        uint midDepositsCount = c.depositsCount();
        uint midCBalance = address(c).balance;

        // Now attempt to withdraw from c as an external attacker by invoking withdraw on c using a try/catch
        // Note: the try/catch is a top-level statement calling c.withdraw
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record observed public state after attacker attempt
        uint afterDepositsCount = c.depositsCount();
        uint afterCBalance = address(c).balance;

        // General rule: if the call from a non-owner reverted then contract balance and depositsCount must be unchanged from mid-state;
        // if it did not revert then it must have been allowed (but since only owner should be allowed, we assert that non-owner attempts always revert).
        // Because this test contract is the deployer/owner of c, any external caller (like 'attacker') is not the owner; but calls in this single transaction use msg.sender = address(this).
        // To model a non-owner call, we require attacker != address(this) and perform the withdraw as msg.sender = this contract; therefore the intended property is:
        // withdraw called by non-owner must revert. Since we cannot impersonate attacker in the call, we instead assert that any withdraw call (when msg.sender == this contract) is either allowed (owner) or, if not owner, must revert and not change state.
        // Concretely: if reverted == true then after-state must equal mid-state (no balance or depositsCount change). If reverted == false then state change is consistent with a successful withdraw by owner: c.balance decreased by withdrawAmount and depositsCount unchanged.

        // Check: depositsCount should never decrease. Also if revert happened, balances unchanged; if not, balance decreased by exactly withdrawAmount (but not underflow).
        assert(
            // depositsCount never decreases
            (afterDepositsCount >= midDepositsCount)
            && (
                reverted
                ? (afterDepositsCount == midDepositsCount && afterCBalance == midCBalance)
                : (midCBalance >= withdrawAmount && afterCBalance + withdrawAmount == midCBalance && afterDepositsCount == midDepositsCount)
            )
        );
    }

    // Accept Ether sent back on successful withdraw
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // This test takes parameters to try actions as either the owner (this contract) or as a different target address.
    // We cannot change msg.sender for calls to c within this single contract, so to simulate a non-owner call
    // we use call on the c contract from this contract but indicate a target address for sendMoney; however
    // withdraw/withdrawAll require msg.sender==owner, so attempting them here should succeed because this
    // InvMutTest deployed C (so it's owner). To check non-owner reverts we rely on sendMoney call failing when
    // forwarded to an external target that reverts; instead, we craft the property about owner-only functions:

    // General rule: when this contract (the owner) calls withdraw or withdrawAll or sendMoney, the call must not revert
    // and the total Ether leaving C must not exceed its balance; depositsCount only increases via fallback payable calls.

    // We include parameters to send Ether into c (amountDeposit) via fallback, and then attempt withdrawals/sendMoney.
    function run(address payable target, uint amountDeposit, uint withdrawAmount, bytes calldata data) public payable {
        require(address(this).balance >= amountDeposit, "insufficient balance for deposit");

        // Record before-state observables
        uint beforeDeposits = c.depositsCount();
        uint beforeCbalance = address(c).balance;

        // Send Ether to c to trigger fallback (which increments depositsCount)
        // Use low-level call to forward Ether to c so fallback executes
        (bool s,) = address(c).call{value: amountDeposit}("\x00");
        // fallback is payable, so call should succeed
        // We don't require s==true to allow exploring both success/failure, but fallback shouldn't revert in provided C

        uint afterDepositCbalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Now perform owner-only actions (this contract is the owner). These should not revert when called by owner.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observables after operations
        uint finalCbalance = address(c).balance;
        uint finalDeposits = c.depositsCount();
        uint thisBalance = address(this).balance;

        // Assert a general rule:
        // 1) depositsCount only increases by the fallback call (by at most 1 here)
        // 2) The contract's balance never increased except by the deposit call, and never decreased below beforeDeposit minus total attempted withdrawals
        // 3) When owner calls withdraw/withdrawAll/sendMoney, they may or may not revert only due to insufficient balance or target call failing,
        //    but depositsCount should not change because of withdrawals; so finalDeposits == afterDeposits.
        // We express a provable invariant: finalDeposits == afterDeposits AND finalCbalance <= afterDepositCbalance

        assert(finalDeposits == afterDeposits && finalCbalance <= afterDepositCbalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to deposit some Ether first (via sending to c to trigger fallback),
    // then attempt owner actions. All state-changing calls on c are top-level statements.
    function run(address payable target, uint amountDeposit, uint withdrawAmount, bytes calldata data) public payable {
        require(address(this).balance >= amountDeposit, "insufficient balance for deposit");

        // Observe before-state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c to trigger fallback (this is a low-level call to address(c) and not a call on c's methods)
        (bool suc, ) = address(c).call{value: amountDeposit}("\x00");
        suc; // ignore success flag in logic; fallback is payable in C

        // Observe after deposit
        uint afterDepositDeposits = c.depositsCount();
        uint afterDepositBalance = address(c).balance;

        // Now, as the owner (this contract deployed C), call withdraw, withdrawAll, and sendMoney.
        // Each call is its own top-level statement.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observe final state
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule to assert:
        // - depositsCount must not increase because of owner-only actions (only fallback increments it),
        //   so finalDeposits equals afterDepositDeposits.
        // - The contract balance cannot have increased as a result of the owner actions (owner actions can only transfer Ether out),
        //   so finalBalance <= afterDepositBalance.
        assert(finalDeposits == afterDepositDeposits && finalBalance <= afterDepositBalance);
    }

    receive() external payable {}
}

