contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params include caller address indicator and amounts/data
    // We cannot change msg.sender when calling c from this contract: all calls originate from this contract
    // So to simulate non-owner calls we rely on the fact that c was deployed by the checker and owner==msg.sender at its deployment
    // In this environment, owner == address that deployed c (the checker), not this contract. Thus this contract is generally NOT owner.

    // We take amounts to send into c via fallback and attempt withdraw; amountSent is used to send Ether into C via fallback
    function run(address targetForSendCall, uint amountSent, uint withdrawAmount, bytes calldata data) public payable {
        require(address(this).balance >= amountSent, "balance for funding missing");
        // record before-values
        uint beforeBalanceC = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Send Ether to c via fallback by calling with value; this will increase depositsCount by 1
        // We use low-level call to trigger fallback; must be top-level statement
        (bool sent, ) = address(c).call{value: amountSent}("\x00");
        // ignore whether send succeeded; if it fails then depositsCount shouldn't increase and balance shouldn't change

        uint midBalanceC = address(c).balance;
        uint midDeposits = c.depositsCount();

        // Now attempt to withdraw from c as this contract (likely non-owner). Capture revert boolean.
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalanceC = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: If withdraw call reverted then C's balance and depositsCount must be unchanged from before that withdraw attempt.
        // Also, if this contract is non-owner, withdraw must revert. But we cannot directly know owner; instead we assert the invariant conditional on revert flag.
        // Express: reverted => (afterBalanceC == midBalanceC && afterDeposits == midDeposits)
        assert(reverted ? (afterBalanceC == midBalanceC && afterDeposits == midDeposits) : true);
    }

    receive() external payable {}
}

contract InvMutTest {
