    // Single public test function
    // Parameters:
    //  - amountFund: amount of wei to send to C to exercise fallback (may be 0)
    //  - withdrawAmount: amount to attempt to withdraw
    // Note: this function is payable to allow funding this contract so it can forward Ether to C.
    function run(uint amountFund, uint withdrawAmount) public payable {
        require(address(this).balance >= amountFund, "not enough balance to fund");

        // Read before-values
        uint beforeBalanceC = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // State-changing call 1: send Ether to C to trigger fallback (top-level statement)
        (bool fundOk, ) = address(c).call{value: amountFund}("");

        // Read mid-values after funding attempt
        uint midBalanceC = address(c).balance;
        uint midDeposits = c.depositsCount();

        // State-changing call 2: attempt withdraw and capture whether it reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Read after-values
        uint afterBalanceC = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if the withdraw call reverted then C's balance and depositsCount must be unchanged by that withdraw attempt
        // (they may have changed earlier due to funding, so we compare to mid-values)
        assert(withdrewReverted ? (afterBalanceC == midBalanceC && afterDeposits == midDeposits) : true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: send some funds to C (via fallback) then attempt withdraw; if withdraw succeeds, balance reduced accordingly
    // Params:
    //  - fundAmount: wei this test contract will send to C to trigger fallback (may be 0)
    //  - withdrawAmount: amount to attempt to withdraw from C
    function run(uint fundAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund");

        // record before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // State-changing call 1: fund C via sending Ether to it (top-level statement)
        (bool sent, ) = address(c).call{value: fundAmount}("\x00");
        sent; // silence unused warning

        // record mid-values (after funding)
        uint midBalance = address(c).balance;
        uint midDeposits = c.depositsCount();

        // State-changing call 2: attempt withdraw and capture revert by try/catch (top-level statement)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // record after-values
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule:
        // If withdraw did not revert then C's balance decreased by exactly withdrawAmount (but not below zero)
        // and depositsCount was not changed by the withdraw call.
